; ZF from extension register 51h bit 2 (flat panel enabled).
panel_active_check:
        push dx                                  ; 0C46
        push ax                                  ; 0C47
        mov dx, 0x3d6                            ; 0C48
        in al, dx                                ; 0C4B
        push ax                                  ; 0C4C
        mov al, 0x51                             ; 0C4D
        call ct_ext_read                         ; 0C4F
        test ah, 4                               ; 0C52
        pop ax                                   ; 0C55
        mov dx, 0x3d6                            ; 0C56
        out dx, al                               ; 0C59
        pop ax                                   ; 0C5A
